import{_ as a,o as t,c as r,a6 as s}from"./chunks/framework.BrkgobfX.js";const f=JSON.parse('{"title":"System One：快思考模型","description":"从卡尼曼的“系统 1 / 系统 2”讲起：System One 模型是什么，它和 LLM 怎么分工，与 JSON 模式、传统分类器、嵌入模型有何不同。","frontmatter":{"title":"System One：快思考模型","description":"从卡尼曼的“系统 1 / 系统 2”讲起：System One 模型是什么，它和 LLM 怎么分工，与 JSON 模式、传统分类器、嵌入模型有何不同。","source":"https://daiw.org/manual/jev/system-one"},"headers":[],"relativePath":"manual/llm/jev/system-one.md","filePath":"manual/llm/jev/system-one.md"}'),n={name:"manual/llm/jev/system-one.md"};function i(l,e,o,d,p,h){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="system-one-快思考模型" tabindex="-1">System One：快思考模型 <a class="header-anchor" href="#system-one-快思考模型" aria-label="Permalink to &quot;System One：快思考模型&quot;">​</a></h1><blockquote><p>从卡尼曼的“系统 1 / 系统 2”讲起：System One 模型是什么，它和 LLM 怎么分工，与 JSON 模式、传统分类器、嵌入模型有何不同。</p></blockquote><p>先做一道小题，别想太久：一个球拍加一个球一共 1.10 美元，球拍比球贵 1 美元，球多少钱？</p><p>多数人脑子里先冒出来的是“10 美分”。可如果球是 10 美分，球拍就得是 1.10 美元，加起来是 1.20 美元——正确答案是 5 美分。心理学家 Shane Frederick 拿这道题考过大学生：普林斯顿有 50%（47/93）、密歇根大学有 56%（164/293）的学生答错了 [1]。</p><p>2002 年诺贝尔经济学奖得主丹尼尔·卡尼曼 [2] 在获奖演讲里用这道题说明：人脑里有一个飞快、自动冒出答案的系统，还有一个慢一些、负责检查的系统，而后者的检查往往相当松懈 [1]。TypeSafe 给自己的模型类别起名“System One”，借的就是这个说法。</p><h2 id="卡尼曼的两套系统" tabindex="-1">卡尼曼的两套系统 <a class="header-anchor" href="#卡尼曼的两套系统" aria-label="Permalink to &quot;卡尼曼的两套系统&quot;">​</a></h2><p>心理学家把人的两类思维过程分别叫作系统 1（System 1）和系统 2（System 2）。这对名字是 Stanovich 和 West 在 2000 年起的，卡尼曼让它们广为人知 [1][5]。他在诺贝尔奖演讲里列了一张对照表 [1]：</p><table tabindex="0"><thead><tr><th>维度</th><th>系统 1（直觉）</th><th>系统 2（推理）</th></tr></thead><tbody><tr><td>速度</td><td>快</td><td>慢</td></tr><tr><td>方式</td><td>并行</td><td>串行</td></tr><tr><td>控制</td><td>自动</td><td>受控</td></tr><tr><td>费力程度</td><td>不费力</td><td>费力</td></tr><tr><td>运作</td><td>联想式</td><td>遵循规则</td></tr><tr><td>可塑性</td><td>学得慢</td><td>灵活</td></tr></tbody></table><p>2011 年出版的《思考，快与慢》（Thinking, Fast and Slow）把这套框架讲给了大众读者；书的简介概括为：系统 1 快速、直觉、带情绪，系统 2 更慢、更审慎、更讲逻辑 [3]。</p><p>演讲里还有两句话值得记住，后面会用到：一是不确定性在直觉里表现得很差；二是“怀疑”属于系统 2 [1]。换句话说，人的快思考擅长给出一个答案，却不擅长同时告诉你“我有几成把握”。</p><h2 id="typesafe-借用的是哪层意思" tabindex="-1">TypeSafe 借用的是哪层意思 <a class="header-anchor" href="#typesafe-借用的是哪层意思" aria-label="Permalink to &quot;TypeSafe 借用的是哪层意思&quot;">​</a></h2><p>TypeSafe 在发布博客的 FAQ 里说，System One 模型这个类名就来自卡尼曼对快速直觉的系统 1 与缓慢审慎的系统 2 的区分 [4]；文档补充说，这里强调的是快速、聚焦的判断 [5]。</p><p>官方对“好问题”的标准也很像系统 1：一个知识丰富的人拿到合适的材料后，几秒钟、甚至一秒钟内就能做出的判断，文档称之为“直觉检查”（gut-check）式的判断 [6][7]。例如“这条消息表达了紧急情绪吗？”是好问题；“分析这条消息并决定最佳处理方案”就不是——那需要慢推理，应该拆成几道小题，再在代码里组合 [7]。</p><p>有意思的是，TypeSafe 自己也承认“系统 1 思维”向来带着“容易出错”的意味，并说他们相信 System One 模型可以做得比其他方案更可靠，理由“以后再讲”[4]。对照卡尼曼那两句话，可以这样理解他们的野心：既要系统 1 的速度，又要一样系统 1 本来不擅长的东西——对自己有几成把握的诚实估计，也就是<a href="/Front2Full/manual/llm/jev/rlcd">第 4 篇</a>要讲的“校准”。这是本专栏的解读，不是官方表述。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>名字只是比喻。卡尼曼的两套系统描述的是人类认知；System One 模型是一种软件接口加一种训练目标的组合，官方没有声称 Jev 模拟了人脑的系统 1。</p></div><h2 id="system-one-模型到底是什么" tabindex="-1">System One 模型到底是什么 <a class="header-anchor" href="#system-one-模型到底是什么" aria-label="Permalink to &quot;System One 模型到底是什么&quot;">​</a></h2><p>按官方文档的定义 [5]：</p><ul><li>System One 模型是一类为软件做快速、结构化决策的 AI 模型：读入一个状态（state，即要判断的文本或图像材料），返回带类型的答案和概率。</li><li>它和 LLM 一样能理解自然语言（自 10 月更新起也支持理解图像），但不写回复、不写代码，也不生成推理过程的解释。可能的答案由你用 Choice（选择）、Score（打分）、Noul（是非）、Box（图像边界框，<code>jev-1.14.0</code> 新增）四种原语事先定义。</li><li>它的概率是对照真实结果优化过的，用来反映不确定性；但校准是在一批预测上衡量的，不保证任何单个答案正确。</li><li>目前官方公开的 System One 模型家族只有 Jev（含 <code>jev-1.14.0</code> 与 <code>jev-1.13.0</code>）[5][8]。</li></ul><p>那它是不是一个“小号 LLM”？官网首页 FAQ 的回答是否定的：Jev 的效率来自为另一种任务做优化，它理解语言，但不生成自由文本，也不当聊天机器人 [9]。发布博客的 FAQ 说得更干脆：Jev 既不小，也不是 LLM [4]。内部到底是什么架构，官方没有公开，见<a href="/Front2Full/manual/llm/jev/parallel-sampler">下一篇</a>。</p><h2 id="和-llm-怎么分工" tabindex="-1">和 LLM 怎么分工 <a class="header-anchor" href="#和-llm-怎么分工" aria-label="Permalink to &quot;和 LLM 怎么分工&quot;">​</a></h2><p>TypeSafe 把软件分成三种架构 [10]：</p><ol><li><strong>传统软件</strong>：由简单、可靠的原语搭成的复杂决策树。</li><li><strong>LLM 智能体</strong>：模型读指令、自己决定下一步；有人盯着时好用，但每多一轮循环，就多一次跑偏的机会。</li><li><strong>AI 驱动的软件</strong>：代码掌握控制流、负责确定性的工作；模型只出现在需要“可编程常识”或需要解读非结构化数据的地方，每个 AI 任务都保持原子化、有约束。</li></ol><p>System One 模型瞄准的是第三种。顺着卡尼曼的比喻，擅长长链推理和生成文字的 LLM 更像系统 2；Jev 的“已知短板”文档也直接把需要更多层间接推理的任务叫作 System Two 任务，建议别交给 Jev [11]。把官方文档里的分工串起来，大致是：</p><ul><li><strong>代码做能精确计算的事</strong>：数数、算术、日期比较一律放在代码里，别问模型 [11]。</li><li><strong>Jev 做窄而快的判断</strong>：分类、路由、打分、核查。官网 FAQ 说它擅长常识判断，而复杂数学、类似下棋的规划这类需要长推理的任务，更适合大型推理模型 [9]。</li><li><strong>LLM 做生成和深推理</strong>：Jev 不生成文本，需要写回复、从自由文本里抽取内容时，交给生成式模型 [11]。</li><li><strong>人和推理模型兜底</strong>：置信度低时不要行动，转人工、请用户澄清，或者交给别的系统 [12]；用官方的话说，由你的代码决定何时行动、何时升级给人或推理模型 [5]。</li></ul><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  IN[&quot;请求或事件&quot;] --&gt; CODE{&quot;代码先处理能精确算的部分&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CODE --&gt;|需要语义判断| JEV[&quot;Jev：几道窄问题一次作答&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CODE --&gt;|需要写文字| LLM[&quot;生成式 LLM&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  JEV --&gt; GATE{&quot;看置信度&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GATE --&gt;|高| ACT[&quot;代码直接执行&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GATE --&gt;|中| ASK[&quot;请用户确认或补充信息&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GATE --&gt;|低| ESC[&quot;转人工或推理模型&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>官方文档里有几种典型的组合方式：</p><ul><li><strong>意图路由</strong>：Jev 先当一个又快又便宜的分类器，判断请求属于哪类、有多复杂，再分给确定性代码、专门的 LLM 或人工 [13]。</li><li><strong>级联抽取</strong>：便宜的小 LLM 先从文档里抽取字段，Jev 对每个字段问一句“这个值是不是源文档里没有的”之类的是非题，有字段亮红灯才升级给昂贵的推理模型 [14]。</li><li><strong>LLM 护栏</strong>：LLM 应用的每条输入和输出都先过一遍 Jev，用一组是非题判断是否越狱、是否涉及伤害，再用一道打分题评估危害程度，阈值写在你自己的代码里 [15]。</li></ul><h2 id="它和这几样东西有什么不同" tabindex="-1">它和这几样东西有什么不同 <a class="header-anchor" href="#它和这几样东西有什么不同" aria-label="Permalink to &quot;它和这几样东西有什么不同&quot;">​</a></h2><h3 id="与-json-模式、结构化输出" tabindex="-1">与 JSON 模式、结构化输出 <a class="header-anchor" href="#与-json-模式、结构化输出" aria-label="Permalink to &quot;与 JSON 模式、结构化输出&quot;">​</a></h3><p>LLM 厂商早就提供了“让模型按格式输出”的功能。以 OpenAI 为例：JSON 模式只保证输出是合法的 JSON；结构化输出（Structured Outputs）更进一步，保证符合你给的 JSON Schema，不会漏掉必填字段，也不会“幻觉”出一个不合法的枚举值 [16]。技术上，这类功能靠约束解码（constrained decoding）：模型每写一个 token（词元，模型处理文字的最小单位），都先把不符合语法的候选屏蔽掉；开源库 Outlines 就用有限状态机实现了这个思路 [17]。</p><p>所以“类型安全”本身并不是 Jev 独有的。差别在别处：</p><ul><li>结构化输出里的模型仍然是逐个 token 写出答案。OpenAI 文档也提醒，结构化输出仍可能包含错误；遇到拒答或触到输出长度上限时，还可能拿不到符合格式的结果 [16]。</li><li>它默认只给一个答案，不给每个选项的概率。</li><li>TypeSafe 认为，把 LLM 硬塞进格式里会浪费掉一部分智能 [9]。一项 2024 年的研究确实发现，格式限制会明显削弱 LLM 的推理能力，而且限制越严，下降越多 [18]；不过这是单项研究，结论与任务和提示方式有关。</li></ul><p>Jev 则从训练开始就只做结构化决策，直接返回每个选项的概率 [9]。</p><h3 id="与传统分类器" tabindex="-1">与传统分类器 <a class="header-anchor" href="#与传统分类器" aria-label="Permalink to &quot;与传统分类器&quot;">​</a></h3><p>以 BERT 为代表的做法，是在预训练模型的输出上接一个分类层：取序列开头 <code>[CLS]</code> 位置的向量，乘上一个 <code>K×H</code> 的矩阵（K 是标签数），再用标注数据微调 [19]。站内有 <a href="https://daiw.org/manual/bit-to-agi/05-transformer/bert-vs-gpt" target="_blank" rel="noreferrer">BERT 与 GPT 的区别</a>可以参考。这类模型又快又便宜，但标签集合在训练时就固定了：换一套标签，就得重新收集数据、重新训练。它输出的“概率”也未必可信——现代深度网络往往比老网络更准，却更过度自信，这一点第 4 篇细说 [20]。</p><p>Jev 的选项则是每次请求时用自然语言现写的，一道 Choice 题最多 255 个选项 [21]。官方说 Jev 不针对单个客户微调，所有账户共用同一套权重，领域知识通过请求里的状态、指令和选项描述注入 [8]。换句话说，你把分类器的“训练”换成了“把选项描述写清楚”。</p><h3 id="与嵌入模型" tabindex="-1">与嵌入模型 <a class="header-anchor" href="#与嵌入模型" aria-label="Permalink to &quot;与嵌入模型&quot;">​</a></h3><p>嵌入模型（embedding model）把一句话变成一个向量，意思相近的句子向量也相近。Sentence-BERT 让“在 1 万个句子里找出最相似的一对”从用 BERT 的约 65 小时缩短到约 5 秒 [22]。站内见 <a href="https://daiw.org/manual/bit-to-agi/05-transformer/what-is-embedding" target="_blank" rel="noreferrer">Embedding 是什么</a>。</p><p>但嵌入只告诉你“有多像”，不回答“是不是”“选哪个”。余弦相似度 0.83 算不算“是退款请求”，得你自己定阈值，甚至再训练一个分类器；相似度本身也不是概率。两者可以搭配：官方的重排序示例先用传统关键词检索 BM25 为每个法律检索问题挑出 30 段候选，再让 Jev 对每个“问题—候选”对逐一判断，官方报告首位命中率从 5% 提升到 18% [23]。</p><h3 id="一张表收尾" tabindex="-1">一张表收尾 <a class="header-anchor" href="#一张表收尾" aria-label="Permalink to &quot;一张表收尾&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>输出</th><th>选项何时确定</th><th>有没有概率</th></tr></thead><tbody><tr><td>JSON 模式、结构化输出</td><td>逐 token 生成、受格式约束的文本</td><td>每次请求（写在 Schema 里）</td><td>默认没有</td></tr><tr><td>传统分类器</td><td>固定标签上的分布</td><td>训练时</td><td>有，但常需额外校准</td></tr><tr><td>嵌入模型</td><td>向量</td><td>不需要选项</td><td>没有，相似度不是概率</td></tr><tr><td>Jev</td><td>你定义的选项上的分布（或边界框）与置信度</td><td>每次请求</td><td>有，官方称已校准</td></tr></tbody></table><p>System One 的“快”到底从哪里来？官方给的答案是“并行采样”。下一篇讲这件事背后的一般原理，以及 TypeSafe 到底公开了多少。👉 <a href="/Front2Full/manual/llm/jev/parallel-sampler">原理一：一次给出全部答案的并行采样</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Daniel Kahneman. “Maps of Bounded Rationality: A Perspective on Intuitive Judgment and Choice.” 诺贝尔奖演讲，2002-12-08. <a href="https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf" target="_blank" rel="noreferrer">nobelprize.org（PDF）</a> —— 球拍与球的题及答错比例、系统 1 / 系统 2 的命名来源与对照表、“不确定性在直觉里表现很差”“怀疑属于系统 2”。</li><li>[2] Nobel Prize Outreach. “Daniel Kahneman – Facts.” <a href="https://www.nobelprize.org/prizes/economic-sciences/2002/kahneman/facts/" target="_blank" rel="noreferrer">nobelprize.org</a> —— 2002 年诺贝尔经济学奖及获奖理由。</li><li>[3] Daniel Kahneman. Thinking, Fast and Slow（中译《思考，快与慢》）. 2011. <a href="https://www.penguinrandomhouse.com/books/89308/thinking-fast-and-slow-by-daniel-kahneman/" target="_blank" rel="noreferrer">Penguin Random House 书目页（有声书版，2011-10-25）</a> —— 出版年份与对两套系统的概括。</li><li>[4] Diogo Almeida（TypeSafe AI）. “Introducing System One Models &amp; Jev.” 2026-09-15. <a href="https://typesafe.ai/blog/introducing-system-one-models-and-jev" target="_blank" rel="noreferrer">typesafe.ai/blog</a> —— FAQ：名字来自卡尼曼、承认“系统 1”有易错的含义、Jev 既不小也不是 LLM。</li><li>[5] TypeSafe AI. “System One.” 官方文档. <a href="https://docs.typesafe.ai/concepts/system-one" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— System One 模型的定义、四种原语、与 LLM 的区别、校准只对一批预测成立、名字来自卡尼曼普及的概念、何时升级给人或推理模型。</li><li>[6] TypeSafe AI. “Introduction.” 官方文档. <a href="https://docs.typesafe.ai/introduction" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— “直觉检查”式判断、把复杂问题拆开。</li><li>[7] TypeSafe AI. “Primitives (Questions).” 官方文档. <a href="https://docs.typesafe.ai/primitives" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 好问题与坏问题的例子、一秒钟内能做出的判断。</li><li>[8] TypeSafe AI. “Models.” 官方文档. <a href="https://docs.typesafe.ai/models" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 当前模型列表（<code>jev-1.14.0</code> 与 <code>jev-1.13.0</code>）、所有账户共用一套权重、不做客户微调。</li><li>[9] TypeSafe AI. 官网首页（含 FAQ）. <a href="https://typesafe.ai/" target="_blank" rel="noreferrer">typesafe.ai</a> —— “是不是小号 LLM”“和 JSON 模式有何不同”“擅长与不擅长什么”三问的官方回答。</li><li>[10] TypeSafe AI. “How to build with TypeSafe.” 官方文档. <a href="https://docs.typesafe.ai/concepts/how-to-build-with-system-one" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 三种软件架构、代码掌握控制流。</li><li>[11] TypeSafe AI. “Model jaggedness.” 官方文档. <a href="https://docs.typesafe.ai/model-jaggedness" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 数数、算术、日期放在代码里；System Two 任务；不擅长生成文本。</li><li>[12] TypeSafe AI. “Confidence.” 官方文档. <a href="https://docs.typesafe.ai/confidence" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 高、中、低三档置信度对应的系统行为。</li><li>[13] TypeSafe AI. “Intent routing.” 官方文档. <a href="https://docs.typesafe.ai/patterns/intent-routing" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 先分类，再分给确定性代码、专门的 LLM 或人工。</li><li>[14] TypeSafe AI. “SDE cascade.” 官方文档 cookbook. <a href="https://docs.typesafe.ai/cookbooks/sde_cascade" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 小模型抽取、Jev 逐字段核查、再升级给推理模型。</li><li>[15] TypeSafe AI. “Guardrails for LLMs.” 官方文档 cookbook. <a href="https://docs.typesafe.ai/cookbooks/llm_guardrails" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 用是非题和打分题筛查 LLM 的输入与输出。</li><li>[16] OpenAI. “Structured model outputs.” OpenAI API 文档. <a href="https://developers.openai.com/api/docs/guides/structured-outputs" target="_blank" rel="noreferrer">developers.openai.com</a> —— JSON 模式与结构化输出的区别、结构化输出仍可能出错、拒答与长度上限等边界情况。</li><li>[17] Brandon T. Willard, Rémi Louf. “Efficient Guided Generation for Large Language Models.” 2023-07. <a href="https://arxiv.org/abs/2307.09702" target="_blank" rel="noreferrer">arXiv:2307.09702</a> —— 用有限状态机约束文本生成（Outlines）。</li><li>[18] Zhi Rui Tam 等. “Let Me Speak Freely? A Study on the Impact of Format Restrictions on Performance of Large Language Models.” 2024-08. <a href="https://arxiv.org/abs/2408.02442" target="_blank" rel="noreferrer">arXiv:2408.02442</a> —— 格式限制削弱推理能力。</li><li>[19] Jacob Devlin 等. “BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding.” 2018-10. <a href="https://arxiv.org/abs/1810.04805" target="_blank" rel="noreferrer">arXiv:1810.04805</a> —— <code>[CLS]</code> 表示加分类层、<code>K×H</code> 的分类权重。</li><li>[20] Chuan Guo 等. “On Calibration of Modern Neural Networks.” 2017-06. <a href="https://arxiv.org/abs/1706.04599" target="_blank" rel="noreferrer">arXiv:1706.04599</a> —— 现代神经网络校准变差。</li><li>[21] TypeSafe AI. “Choice.” 官方文档. <a href="https://docs.typesafe.ai/primitives/choice" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— 一道 Choice 题最多 255 个选项。</li><li>[22] Nils Reimers, Iryna Gurevych. “Sentence-BERT: Sentence Embeddings using Siamese BERT-Networks.” 2019-08. <a href="https://arxiv.org/abs/1908.10084" target="_blank" rel="noreferrer">arXiv:1908.10084</a> —— 句向量加余弦相似度，找最相似句对从约 65 小时降到约 5 秒。</li><li>[23] TypeSafe AI. “Re-ranking.” 官方文档 cookbook. <a href="https://docs.typesafe.ai/cookbooks/rerank_typesafe" target="_blank" rel="noreferrer">docs.typesafe.ai</a> —— BM25 初筛加 Jev 重排序，首位命中率 5% 到 18%（官方报告）。</li></ul>`,44)])])}const u=a(n,[["render",i]]);export{f as __pageData,u as default};
